// firmware/src/fonts/FreeSansBold48pt7b.h — the big countdown face.
//
// GNU FreeSans Bold at 48 pt (digits ~70 px tall), the same family and the same
// generator as the FreeSans fonts bundled with Adafruit GFX — just a size the
// library doesn't ship. Only '0'..'z' (0x30-0x7A) is included: the digits, ':'
// and the letters of "now" are all the big number ever shows.
//
// Regenerate (freetype2 required):
//   curl -LO https://ftp.gnu.org/gnu/freefont/freefont-ttf-20120503.zip && unzip freefont-ttf-20120503.zip
//   cc $(pkg-config --cflags freetype2) "<Adafruit GFX Library>/fontconvert/fontconvert.c" \
//      $(pkg-config --libs freetype2) -o fontconvert
//   ./fontconvert freefont-20120503/FreeSansBold.ttf 48 48 122 > FreeSansBold48pt7b.h
//
// GNU FreeFont is GPLv3 with the font exception (embedding in a product does
// not make the product a derived work).
